-- Correct Daniel Stitchsong and Mivin Shadowweave recipe placeholder costs/gates.
-- Client/core pins: 1.60.1.70862 / 343fe6fb95076e09575156c8b88d155914003b78.
-- GearInsight names both faction vendors at the same per-recipe Merchant's Favor price.
-- https://gearinsight.app/wow/en/forever/professions
-- Individual Wowhead Forever item tooltips corroborate every reputation rank.
-- Existing Horde rows and pinned client tables resolve exact cost/condition IDs.
-- Modify only untouched placeholder rows with matching reference stock and live spawns.
-- Never edit after deployment; use a later correction file. Reapplication changes nothing.
CREATE TEMPORARY TABLE `everlake_cloth_leather_prices` (
 `vendor` int unsigned NOT NULL,
 `reference_vendor` int unsigned NOT NULL,
 `item` int unsigned NOT NULL,
 `cost` int unsigned NOT NULL,
 `condition_id` int unsigned NOT NULL,
 PRIMARY KEY (`vendor`,`item`)
);
UPDATE `npc_vendor` a
JOIN `everlake_cloth_leather_prices` s ON s.`vendor` = a.`entry` AND s.`item` = a.`item`
JOIN `npc_vendor` h ON h.`entry` = s.`reference_vendor` AND h.`item` = a.`item` AND h.`type` = 1
 AND h.`ExtendedCost` = s.`cost` AND h.`PlayerConditionID` = s.`condition_id`
SET a.`ExtendedCost` = s.`cost`, a.`PlayerConditionID` = s.`condition_id`
WHERE a.`type` = 1 AND a.`slot` = 0 AND a.`ExtendedCost` = 0 AND a.`PlayerConditionID` = 0
 AND a.`maxcount` = 0 AND a.`incrtime` = 0 AND a.`VerifiedBuild` = 0
 AND a.`IgnoreFiltering` = 0 AND a.`BonusListIDs` IS NULL
 AND ((s.`vendor` = 256734 AND s.`reference_vendor` = 248201
 AND EXISTS (SELECT 1 FROM `creature_template` t WHERE t.`entry` = 256734 AND t.`name` = 'Daniel Stitchsong' AND (t.`npcflag` & 128) <> 0)
 AND EXISTS (SELECT 1 FROM `creature_template` t WHERE t.`entry` = 248201 AND t.`name` = 'Pawani' AND (t.`npcflag` & 128) <> 0))
 OR (s.`vendor` = 256735 AND s.`reference_vendor` = 248202
 AND EXISTS (SELECT 1 FROM `creature_template` t WHERE t.`entry` = 256735 AND t.`name` = 'Mivin Shadowweave' AND (t.`npcflag` & 128) <> 0)
 AND EXISTS (SELECT 1 FROM `creature_template` t WHERE t.`entry` = 248202 AND t.`name` = 'Jim''bek' AND (t.`npcflag` & 128) <> 0)))
 AND EXISTS (SELECT 1 FROM `creature` c WHERE c.`id` = s.`vendor` AND c.`map` = 0)
 AND EXISTS (SELECT 1 FROM `creature` c WHERE c.`id` = s.`reference_vendor` AND c.`map` = 1);
DROP TEMPORARY TABLE `everlake_cloth_leather_prices`;
